-- Genometrics demo dataset.
-- Idempotent: re-running replaces the four demo projects and everything inside them,
-- including samples added later to those projects. Other projects stay in place.
-- AI questions outside the three demo rows stay in place.
--
-- Login (auth enabled): dev@genometrics.local / dev
--                        analyst@genometrics.local / demo
-- With auth disabled the API signs in as dev@genometrics.local, which owns this data.
--
-- Files listed here are metadata only. Metrics are already stored, so dashboards,
-- compare, explore, history, reports, and QC work without the raw FASTQ/VCF bytes.
-- Re-processing a demo file fails until a real file is uploaded to that storage path.
--
-- Loaded by the demo-data service in docker compose, after the API has migrated the schema.

BEGIN;


ON CONFLICT (email) DO NOTHING;


DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM users WHERE lower(email) = 'dev@genometrics.local') THEN
        RAISE EXCEPTION 'demo seed requires dev@genometrics.local';
    END IF;
END $$;


DELETE FROM ai_interactions WHERE id IN ('90000000-0000-4000-8000-000000000001'::uuid, '90000000-0000-4000-8000-000000000002'::uuid, '90000000-0000-4000-8000-000000000003'::uuid);
DELETE FROM qc_check_facts WHERE analysis_id IN ('40000000-0000-4000-8000-000000000001'::uuid, '40000000-0000-4000-8000-000000000002'::uuid, '40000000-0000-4000-8000-000000000003'::uuid, '40000000-0000-4000-8000-000000000004'::uuid, '40000000-0000-4000-8000-000000000005'::uuid, '40000000-0000-4000-8000-000000000006'::uuid, '40000000-0000-4000-8000-000000000007'::uuid, '40000000-0000-4000-8000-000000000008'::uuid, '40000000-0000-4000-8000-000000000009'::uuid, '40000000-0000-4000-8000-000000000010'::uuid, '40000000-0000-4000-8000-000000000011'::uuid, '40000000-0000-4000-8000-000000000012'::uuid);
