SELECT '90000000-0000-4000-8000-000000000001'::uuid, u.id, $qu$Which germline sample has the higher mean quality?$qu$, $an$NA12878-germline mean quality is 34.8 Phred. Liver-RNAseq is 33.6 Phred. NA12878-tumor is 24.1 Phred and is below the pass threshold of 28.$an$, 'deterministic', $js$["query_metrics"]$js$, $js$[{"analysisId":"40000000-0000-4000-8000-000000000001","sampleId":"20000000-0000-4000-8000-000000000001","metric":"mean_quality","value":34.8,"unit":"Phred"},{"analysisId":"40000000-0000-4000-8000-000000000009","sampleId":"20000000-0000-4000-8000-000000000005","metric":"mean_quality","value":33.6,"unit":"Phred"},{"analysisId":"40000000-0000-4000-8000-000000000004","sampleId":"20000000-0000-4000-8000-000000000002","metric":"mean_quality","value":24.1,"unit":"Phred"}]$js$, TIMESTAMPTZ '2026-10-08 15:10:00+00'
FROM users u WHERE lower(u.email) = 'dev@genometrics.local';

SELECT '90000000-0000-4000-8000-000000000002'::uuid, u.id, $qu$Compare variant counts for HG001 and HG002.$qu$, $an$HG001-germline has 3842110 variants. HG002-germline has 3910440 variants. Both callsets are mostly PASS.$an$, 'deterministic', $js$["query_metrics"]$js$, $js$[{"analysisId":"40000000-0000-4000-8000-000000000011","sampleId":"20000000-0000-4000-8000-000000000007","metric":"variant_count","value":3842110,"unit":"variants"},{"analysisId":"40000000-0000-4000-8000-000000000012","sampleId":"20000000-0000-4000-8000-000000000008","metric":"variant_count","value":3910440,"unit":"variants"}]$js$, TIMESTAMPTZ '2026-10-08 15:22:00+00'
FROM users u WHERE lower(u.email) = 'dev@genometrics.local';

SELECT '90000000-0000-4000-8000-000000000003'::uuid, u.id, $qu$Why did the tumor library fail quality control?$qu$, $an$NA12878-tumor duplication rate is 38.0 percent, GC content is outside 40-60 percent, N content is 2.4 percent, and adapter hits exceed 5 percent of sampled reads. Overall QC is WARN.$an$, 'deterministic', $js$["query_metrics"]$js$, $js$[{"analysisId":"40000000-0000-4000-8000-000000000004","sampleId":"20000000-0000-4000-8000-000000000002","metric":"duplication_rate","value":38.0,"unit":"%"},{"analysisId":"40000000-0000-4000-8000-000000000004","sampleId":"20000000-0000-4000-8000-000000000002","metric":"gc_content","value":62.4,"unit":"%"},{"analysisId":"40000000-0000-4000-8000-000000000004","sampleId":"20000000-0000-4000-8000-000000000002","metric":"n_content","value":2.4,"unit":"%"}]$js$, TIMESTAMPTZ '2026-10-09 11:05:00+00'
FROM users u WHERE lower(u.email) = 'dev@genometrics.local';


DO $$
BEGIN
    IF (SELECT count(*) FROM projects WHERE id IN ('10000000-0000-4000-8000-000000000001'::uuid, '10000000-0000-4000-8000-000000000002'::uuid, '10000000-0000-4000-8000-000000000003'::uuid, '10000000-0000-4000-8000-000000000004'::uuid)) <> 4 THEN
        RAISE EXCEPTION 'demo seed did not insert the four demo projects';
    END IF;
    IF (SELECT count(*) FROM analyses WHERE id IN ('40000000-0000-4000-8000-000000000001'::uuid, '40000000-0000-4000-8000-000000000002'::uuid, '40000000-0000-4000-8000-000000000003'::uuid, '40000000-0000-4000-8000-000000000004'::uuid, '40000000-0000-4000-8000-000000000005'::uuid, '40000000-0000-4000-8000-000000000006'::uuid, '40000000-0000-4000-8000-000000000007'::uuid, '40000000-0000-4000-8000-000000000008'::uuid, '40000000-0000-4000-8000-000000000009'::uuid, '40000000-0000-4000-8000-000000000010'::uuid, '40000000-0000-4000-8000-000000000011'::uuid, '40000000-0000-4000-8000-000000000012'::uuid) AND status = 'DONE') <> 8 THEN
        RAISE EXCEPTION 'demo seed DONE analyses mismatch';
    END IF;
    IF (SELECT count(*) FROM fastq_metrics WHERE analysis_id IN ('40000000-0000-4000-8000-000000000001'::uuid, '40000000-0000-4000-8000-000000000002'::uuid, '40000000-0000-4000-8000-000000000003'::uuid, '40000000-0000-4000-8000-000000000004'::uuid, '40000000-0000-4000-8000-000000000005'::uuid, '40000000-0000-4000-8000-000000000006'::uuid, '40000000-0000-4000-8000-000000000007'::uuid, '40000000-0000-4000-8000-000000000008'::uuid, '40000000-0000-4000-8000-000000000009'::uuid, '40000000-0000-4000-8000-000000000010'::uuid, '40000000-0000-4000-8000-000000000011'::uuid, '40000000-0000-4000-8000-000000000012'::uuid)) <> 3 THEN
        RAISE EXCEPTION 'demo seed FASTQ metrics mismatch';
    END IF;
    IF (SELECT count(*) FROM vcf_metrics WHERE analysis_id IN ('40000000-0000-4000-8000-000000000001'::uuid, '40000000-0000-4000-8000-000000000002'::uuid, '40000000-0000-4000-8000-000000000003'::uuid, '40000000-0000-4000-8000-000000000004'::uuid, '40000000-0000-4000-8000-000000000005'::uuid, '40000000-0000-4000-8000-000000000006'::uuid, '40000000-0000-4000-8000-000000000007'::uuid, '40000000-0000-4000-8000-000000000008'::uuid, '40000000-0000-4000-8000-000000000009'::uuid, '40000000-0000-4000-8000-000000000010'::uuid, '40000000-0000-4000-8000-000000000011'::uuid, '40000000-0000-4000-8000-000000000012'::uuid)) <> 4 THEN
        RAISE EXCEPTION 'demo seed VCF metrics mismatch';
    END IF;
END $$;

COMMIT;

